let rows=[],rowOffset=0,current=-1,part=0,chunk='',chunkOffset=0,chunkTotal=0;
function prefs(){try{return JSON.parse(localStorage.getItem('mobile-appearance')||'{}')}catch{return {}}}
function mobileTheme(){const data={accent:$('mobileAccent').value,opacity:$('mobileOpacity').value,blur:$('mobileBlur').value};localStorage.setItem('mobile-appearance',JSON.stringify(data));document.documentElement.style.setProperty('--app-panel',`rgba(255,255,255,${Number(data.opacity)/100})`);document.documentElement.style.setProperty('--app-bg','#f5f3ee');document.documentElement.style.setProperty('--app-accent',data.accent);document.documentElement.style.setProperty('--reader-button-opacity',String(Number(data.opacity)/100));document.querySelectorAll('.card').forEach(x=>x.style.backdropFilter=`blur(${data.blur}px)`);document.querySelectorAll('button:not(.secondary):not(.danger):not(.home-entry)').forEach(x=>x.style.setProperty('background-color',data.accent));const image=localStorage.getItem('mobile-background');document.body.style.backgroundImage=image?`url(${image})`:'';document.body.style.backgroundSize='cover';document.body.style.backgroundAttachment='fixed'}
window.mobileBackground=function(file){
  if(!file)return;
  if(!file.type.startsWith('image/'))return notice('请选择图片文件');
  if(file.size>30_000_000)return notice('背景图片请小于 30 MB');
  const reader=new FileReader();reader.onerror=()=>notice('读取背景图片失败');
  reader.onload=()=>{const image=new Image();image.onerror=()=>notice('无法解码这张图片，请尝试 JPG 或 PNG');image.onload=()=>{
    const scale=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');
    canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));
    canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
    try{localStorage.setItem('mobile-background',canvas.toDataURL('image/jpeg',.78));mobileTheme();notice('背景图片已更新')}
    catch{notice('图片保存失败，请选择尺寸更小的图片')}
  };image.src=reader.result};reader.readAsDataURL(file);
};
const appearance=prefs();$('mobileAccent').value=appearance.accent||'#176b70';$('mobileOpacity').value=appearance.opacity||95;$('mobileBlur').value=appearance.blur||6;mobileTheme();
window.mobileHome=()=>tab('home');window.mobileReader=()=>{tab('reader');$('readArchive').innerHTML='<option value="">选择知识库</option>'+archives.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('');$('readArchive').value=archiveId||'';if(archiveId)readerArchive()};
