window.readerModeSet=()=>{part=0;$('mobileReaderShell').dataset.mode=$('readMode').value;readerPaint()};
window.readerStyle=()=>{const box=$('mobileReaderShell'),font=$('readFont')?.value||'system',margin=Number($('readPageMargin')?.value||24),leading=Number($('readLineSpacing')?.value||180)/100,spacing=Number($('readLetterSpacing')?.value||0),align=$('readAlign')?.value||'left';box.style.setProperty('--reader-size',$('readSize').value+'px');box.style.setProperty('--reader-bg',$('readBg').value);box.style.setProperty('--reader-fg',$('readFg').value);box.style.setProperty('--reader-font',font==='serif'?'serif':font==='mono'?'monospace':'system-ui,sans-serif');box.style.setProperty('--reader-page-margin',margin+'px');box.style.setProperty('--reader-leading',String(leading));box.style.setProperty('--reader-letter-spacing',spacing+'px');box.style.setProperty('--reader-align',align);mobilePageKey='';const old=JSON.parse(localStorage.getItem('mobile-reader-style')||'{}');localStorage.setItem('mobile-reader-style',JSON.stringify({...old,size:$('readSize').value,bg:$('readBg').value,fg:$('readFg').value,mode:$('readMode').value,font,margin,leading,spacing,align}));readerPaint()};
function pageChars(){const box=$('readContent');return Math.max(250,Math.floor((box.clientWidth||350)*(box.clientHeight||600)/Math.pow(Number($('readSize').value),2)*1.3))}
let mobilePageKey='',mobilePageOffsets=[0,0];
function mobilePages(){const box=$('readContent');if($('readMode').value!=='horizontal')return;const css=getComputedStyle(box),key=[chunk,box.clientWidth,box.clientHeight,css.font,css.lineHeight,css.letterSpacing,css.padding].join('|');if(key===mobilePageKey)return;mobilePageKey=key;mobilePageOffsets=[0];if(!chunk){mobilePageOffsets.push(0);return}const measure=document.createElement('div');measure.style.cssText=`position:absolute;left:-100000px;top:0;box-sizing:border-box;width:${box.clientWidth}px;height:${box.clientHeight}px;padding:${css.padding};font:${css.font};line-height:${css.lineHeight};letter-spacing:${css.letterSpacing};white-space:pre-wrap;overflow-wrap:anywhere;overflow:hidden;visibility:hidden`;document.body.appendChild(measure);try{while(mobilePageOffsets.at(-1)<chunk.length){const start=mobilePageOffsets.at(-1);let low=start+1,high=chunk.length,best=low;while(low<=high){const mid=Math.floor((low+high)/2);measure.textContent=chunk.slice(start,mid);if(measure.scrollHeight<=measure.clientHeight+1){best=mid;low=mid+1}else high=mid-1}if(best<chunk.length&&best>start+12){const boundary=chunk.lastIndexOf('\n',best);if(boundary>start+(best-start)*.65)best=boundary+1}mobilePageOffsets.push(Math.max(start+1,best))}}finally{measure.remove()}}
function readerPaint(){const box=$('readContent');if($('readMode').value==='scroll'){box.textContent=chunk;box.scrollTop=0}else{mobilePages();part=Math.min(part,mobilePageOffsets.length-2);box.textContent=chunk.slice(mobilePageOffsets[part],mobilePageOffsets[part+1])}$('readProgress').textContent=current>=0?`${rows[current].title} · ${Math.min(chunkTotal,chunkOffset+(mobilePageOffsets[part+1]||0))}/${chunkTotal} 字`:'请选择章节'}
window.readerTurn=delta=>{if(current<0)return;const box=$('readContent');if($('readMode').value==='scroll'){if(delta>0&&box.scrollTop+box.clientHeight<box.scrollHeight-12){box.scrollBy({top:box.clientHeight*.85,behavior:'smooth'});return}if(delta<0&&box.scrollTop>12){box.scrollBy({top:-box.clientHeight*.85,behavior:'smooth'});return}}else{const next=part+delta;if(next>=0&&next*pageChars()<chunk.length){part=next;if($('readMode').value==='curl'){$('mobileReaderShell').classList.remove('turning');void $('mobileReaderShell').offsetWidth;$('mobileReaderShell').classList.add('turning')}readerPaint();return}}if(delta>0&&chunkOffset+chunk.length<chunkTotal){req('readerSlice',{chapter_id:rows[current].id,offset:chunkOffset+chunk.length,limit:6000});return}if(delta<0&&chunkOffset>0){req('readerSlice',{chapter_id:rows[current].id,offset:Math.max(0,chunkOffset-6000),limit:6000});return}const next=current+delta;if(next>=0&&next<rows.length){readerChapter(next);return}if(delta>0&&rowOffset+rows.length<readerTotal){req('readerBrowse',{archive_id:Number($('readArchive').value),offset:rowOffset+40});return}notice('已经到达书籍边界')};
window.readerRewrite=()=>{if(current<0)return notice('先选择章节');const id=rows[current].id;if(Number($('readArchive').value)!==archiveId)selectArchive(Number($('readArchive').value));selectChapter(id);tab('rewrite')};
let readerTotal=0;const original=window.nativeEvent;window.nativeEvent=(type,data)=>{if(type==='readerBrowse'){if(Number($('readArchive').value)!==data.archive_id)return;rowOffset=data.offset;readerTotal=data.total;rows=data.rows||[];$('readChapter').innerHTML=rows.map((r,i)=>`<option value="${i}">${esc(r.title)}</option>`).join('');if(rows.length)readerChapter(0);return}if(type==='readerSlice'){if(current<0||data.chapter_id!==rows[current].id)return;chunk=data.text||'';chunkOffset=data.offset;chunkTotal=data.total;part=0;readerPaint();return}original(type,data)};
const saved=JSON.parse(localStorage.getItem('mobile-reader-style')||'{}');$('readSize').value=saved.size||20;$('readBg').value=saved.bg||'#f6f0e5';$('readFg').value=saved.fg||'#302b27';$('readMode').value=saved.mode||'scroll';readerModeSet();readerStyle();
let x=0;$('readContent').addEventListener('touchstart',e=>{x=e.touches[0].clientX},{passive:true});$('readContent').addEventListener('touchend',e=>{if($('readMode').value==='scroll')return;const dx=e.changedTouches[0].clientX-x;if(Math.abs(dx)>50)readerTurn(dx<0?1:-1)},{passive:true});$('readContent').addEventListener('scroll',()=>{if($('readMode').value==='scroll'&&chunkOffset+chunk.length<chunkTotal&&$('readContent').scrollTop+$('readContent').clientHeight>=$('readContent').scrollHeight-20)readerTurn(1)},{passive:true});
