let touchStartX=0,touchStartY=0,suppressTap=false;
const content=$('readContent');content.addEventListener('touchstart',e=>{touchStartX=e.touches[0].clientX;touchStartY=e.touches[0].clientY;suppressTap=false},{passive:true});
content.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchStartX,dy=e.changedTouches[0].clientY-touchStartY;if(Math.abs(dx)>22||Math.abs(dy)>22)suppressTap=true;if($('readMode').value==='scroll'&&Math.abs(dy)>70){if(dy<0&&content.scrollTop+content.clientHeight>=content.scrollHeight-24)readerTurn(1);else if(dy>0&&content.scrollTop<=24)readerTurn(-1)}},{passive:true});
