let readerShowingRewrite=false;
function updateReaderMenu(){const chapter=rows[current];const name=chapter?.title||'请选择章节';const book=archives.find(a=>Number(a.id)===Number($('readArchive').value));$('readerChapterHeading').textContent=book?.name||'请选择书籍';$('readerChapterFoot').textContent=name;const show=!!chapter?.rewritten;$('readerOriginalAction').hidden=!show;$('readerOriginalAction').querySelector('span').textContent=readerShowingRewrite?'显示原文':'显示改写';}
