window.readerChapter=index=>{if(index<0||index>=rows.length)return;current=index;part=0;chunkOffset=0;chunk='';readerShowingRewrite=!!rows[index].rewritten;$('readChapter').value=String(index);updateReaderMenu();readCurrentSlice(0)};
