window.readerGoChapter=delta=>{if(current+delta>=0&&current+delta<rows.length)readerChapter(current+delta);else readerTurn(delta)};
function readerSlide(delta){const shell=$('mobileReaderShell');shell.classList.remove('slide-next','slide-prev');void shell.offsetWidth;shell.classList.add(delta>0?'slide-next':'slide-prev')}
window.readerTurn=delta=>{if(current<0)return;const box=$('readContent');if($('readMode').value==='scroll'){if(delta>0&&box.scrollTop+box.clientHeight<box.scrollHeight-12){box.scrollBy({top:box.clientHeight*.85,behavior:'smooth'});return}if(delta<0&&box.scrollTop>12){box.scrollBy({top:-box.clientHeight*.85,behavior:'smooth'});return}}else{const next=part+delta;if(next>=0&&next*pageChars()<chunk.length){part=next;readerSlide(delta);readerPaint();return}}if(delta>0&&chunkOffset+chunk.length<chunkTotal){readCurrentSlice(chunkOffset+chunk.length);if($('readMode').value==='horizontal')readerSlide(delta);return}if(delta<0&&chunkOffset>0){readCurrentSlice(Math.max(0,chunkOffset-6000));if($('readMode').value==='horizontal')readerSlide(delta);return}const next=current+delta;if(next>=0&&next<rows.length){readerChapter(next);if($('readMode').value==='horizontal')readerSlide(delta);return}if(delta>0&&rowOffset+rows.length<readerTotal){req('readerBrowse',{archive_id:Number($('readArchive').value),offset:rowOffset+40});return}notice('已经到达书籍边界')};
