  if(index<0||index>=rows.length)return;
  const key=readerKey(index,offset,rewritten);
  if(readerCache.has(key)||readerPending.has(key))return;
  readerPending.add(key);req('readerPrefetch',{chapter_id:rows[index].id,offset,limit:6000,rewritten});
